mapper.select:
SELECT c.id AS caseId, c.case_no AS caseNo, result.id AS resultId, report.version, report.signed_at AS signedAt, report.signer_name_snapshot AS signerName, review.conclusion FROM analysis_report report JOIN analysis_result result ON result.id = report.result_id JOIN analysis_task task ON task.id = result.task_id JOIN medical_case c ON c.id = task.case_id JOIN patient_profile p ON p.id = c.patient_id LEFT JOIN analysis_review review ON review.result_id = result.id WHERE p.account_user_id = #{userId} AND c.status != 'DELETED' AND report.status = 'SIGNED'
AND (c.case_no = #{caseReference} OR (#{caseId} IS NOT NULL AND c.id = #{caseId}))
ORDER BY report.signed_at DESC, report.id DESC LIMIT #{offset}, #{pageSize}
